# BillingSDK: Pricing page


### 1. Plan catalogue

`pricing-table-one` takes BillingSDK's `Plan[]`, not an arbitrary shape. Adding the component generates
`lib/billingsdk-config.ts`, which exports the `Plan` interface and a sample `plans` array — edit that array
rather than defining your own type. Prices are display **strings** (`monthlyPrice`, `yearlyPrice`) and
`features` are objects. The amount actually charged comes from the Dodo product catalogue (always in the
smallest currency unit), so treat this file as a mirror of the dashboard and reconcile it when you change a
price.

```typescript
// lib/billingsdk-config.ts (generated by `add pricing-table-one`; edit the plans)
export interface Plan {
  id: string;
  title: string;
  description: string;
  highlight?: boolean;
  type?: 'monthly' | 'yearly';
  currency?: string;
  monthlyPrice: string;
  yearlyPrice: string;
  buttonText: string;
  badge?: string;
  features: {
    name: string;
    icon: string;
    iconColor?: string;
  }[];
}

export const plans: Plan[] = [
  {
    id: 'starter',
    title: 'Starter',
    description: 'For individuals getting started.',
    currency: '$',
    monthlyPrice: '9',
    yearlyPrice: '90',
    buttonText: 'Choose Starter',
    features: [
      { name: '100 requests', icon: 'check' },
      { name: 'Basic support', icon: 'check' },
      { name: '1 project', icon: 'check' },
    ],
  },
  {
    id: 'pro',
    title: 'Pro',
    description: 'For teams running in production.',
    currency: '$',
    monthlyPrice: '29',
    yearlyPrice: '290',
    buttonText: 'Choose Pro',
    badge: 'Most popular',
    highlight: true,
    features: [
      { name: 'Unlimited requests', icon: 'check' },
      { name: 'Priority support', icon: 'check' },
      { name: '10 projects', icon: 'check' },
    ],
  },
];
```

The generated file is the contract for your installed version; if its `Plan` differs from the above, follow
the file. `onPlanSelect` receives only the plan `id`, so the ids here are the slugs the server maps below.

This example sells **monthly plans only**: `yearlyPrice` is required by the `Plan` type and is displayed,
but the server map below has only monthly products. To sell yearly too, create the yearly products in Dodo,
track the table's billing-period toggle in your own state (it is not passed to `onPlanSelect`), send it with
the plan id, and key the server map by plan and period (for example `pro:yearly`).

### 2. Product id map — server only

Never let the browser choose an arbitrary `product_id`. Map the public plan slug to a `pdt_` id on the
server and reject anything else.

```typescript
// lib/plan-products.server.ts
import 'server-only';

// Keys must match the `id`s in lib/billingsdk-config.ts.
const PRODUCT_IDS: Readonly<Record<string, string>> = {
  starter: 'pdt_starter_monthly',
  pro: 'pdt_pro_monthly',
};

export function productIdForPlan(value: unknown): string | null {
  if (typeof value !== 'string' || !Object.hasOwn(PRODUCT_IDS, value)) return null;
  return PRODUCT_IDS[value];
}
```

### 3. Checkout route

```typescript
// app/api/checkout/route.ts
import { NextResponse } from 'next/server';
import { dodo } from '@/lib/dodopayments';
import { productIdForPlan } from '@/lib/plan-products.server';
import { getCurrentUser } from '@/lib/auth';

export async function POST(request: Request) {
  const user = await getCurrentUser();
  if (!user) {
    return NextResponse.json({ error: 'Not authenticated' }, { status: 401 });
  }

  const body: unknown = await request.json();
  const planId = (body as { planId?: unknown }).planId;
  const productId = productIdForPlan(planId);

  if (!productId) {
    return NextResponse.json({ error: 'Unknown plan' }, { status: 400 });
  }

  try {
    const session = await dodo.checkoutSessions.create({
      product_cart: [{ product_id: productId, quantity: 1 }],
      customer: { email: user.email, name: user.name },
      return_url: `${process.env.NEXT_PUBLIC_APP_URL}/billing/return`,
      cancel_url: `${process.env.NEXT_PUBLIC_APP_URL}/pricing`,
      metadata: { app_user_id: user.id },
    });

    if (!session.checkout_url) {
      return NextResponse.json({ error: 'No checkout URL returned' }, { status: 502 });
    }

    return NextResponse.json({ checkoutUrl: session.checkout_url });
  } catch (error) {
    console.error('Checkout session creation failed', error);
    return NextResponse.json({ error: 'Could not start checkout' }, { status: 500 });
  }
}
```

`checkout_url` is nullable — it is absent when the session is created with `payment_method_id` — so guard
it rather than redirecting to `undefined`. Checkout URLs are single-use and normally expire after 24 hours.

Use `checkoutSessions.create`. `payments.create` and `subscriptions.create` are deprecated for new
integrations. Checkout parameters are covered in depth in the `checkout-integration` skill.

### 4. Client component

```tsx
// components/pricing-plans.tsx
'use client';

import { useState } from 'react';
import { PricingTableOne } from '@/components/billingsdk/pricing-table-one';
import { plans } from '@/lib/billingsdk-config';

export function PricingPlans() {
  const [error, setError] = useState<string | null>(null);

  async function handlePlanSelect(planId: string) {
    setError(null);
    try {
      const response = await fetch('/api/checkout', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ planId }),
      });

      if (!response.ok) {
        setError('Could not start checkout. Please try again.');
        return;
      }

      const { checkoutUrl } = (await response.json()) as { checkoutUrl: string };
      window.location.href = checkoutUrl;
    } catch {
      setError('Network error. Please try again.');
    }
  }

  return (
    <>
      <PricingTableOne
        plans={plans}
        title="Choose your plan"
        description="Select the plan that works best for you"
        onPlanSelect={handlePlanSelect}
        theme="classic"
        size="medium"
      />
      {error ? <p role="alert">{error}</p> : null}
    </>
  );
}
```

Render `<PricingPlans />` from `app/pricing/page.tsx`. Nothing secret crosses into the client component:
it sends a plan slug and receives a URL.

# Dodo Payments Checkout Integration: Overlay Checkout


Use the `dodopayments-checkout` package for overlay or inline checkout that stays on your site.

### Installation

```bash
npm install dodopayments-checkout
```

### Server Route

Create the Checkout Session on the server. The browser sends a public plan slug, while the server derives
the customer from the authenticated user and maps the slug to an allowlisted product id.

```typescript
// app/api/overlay-checkout/route.ts
import { NextResponse } from 'next/server';
import DodoPayments from 'dodopayments';
import { getCurrentUser } from '@/lib/auth';

const client = new DodoPayments({
  bearerToken: process.env.DODO_PAYMENTS_API_KEY!,
  environment: process.env.NODE_ENV === 'production' ? 'live_mode' : 'test_mode'
});

type PlanId = 'starter' | 'pro';

const PRODUCT_IDS: Record<PlanId, string> = {
  starter: 'pdt_starter_monthly',
  pro: 'pdt_pro_monthly'
};

export async function POST(request: Request) {
  const user = await getCurrentUser();
  if (!user) {
    return NextResponse.json({ error: 'Not authenticated' }, { status: 401 });
  }

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid request body' }, { status: 400 });
  }

  if (!body || typeof body !== 'object') {
    return NextResponse.json({ error: 'Invalid request body' }, { status: 400 });
  }

  const { planId, quantity = 1 } = body as {
    planId?: unknown;
    quantity?: unknown;
  };
  const productId = typeof planId === 'string'
    ? PRODUCT_IDS[planId as PlanId]
    : undefined;

  if (!productId) {
    return NextResponse.json({ error: 'Unknown plan' }, { status: 400 });
  }

  if (!Number.isInteger(quantity) || (quantity as number) < 1) {
    return NextResponse.json(
      { error: 'Quantity must be a positive integer' },
      { status: 400 }
    );
  }

  try {
    const session = await client.checkoutSessions.create({
      product_cart: [{ product_id: productId, quantity: quantity as number }],
      customer: { email: user.email, name: user.name },
      metadata: { app_user_id: user.id },
      return_url: `${process.env.NEXT_PUBLIC_APP_URL}/checkout/success`
    });

    if (!session.checkout_url) {
      return NextResponse.json({ error: 'Checkout URL was not returned' }, { status: 502 });
    }

    return NextResponse.json({ checkoutUrl: session.checkout_url });
  } catch (error) {
    console.error('Overlay checkout error:', error);
    return NextResponse.json({ error: 'Failed to create checkout' }, { status: 500 });
  }
}
```

### Browser Overlay and Inline Modes

Browser code calls the server route and receives only the checkout URL. The Dodo Payments API bearer token
stays in the server route and is never sent to the browser.

```typescript
// lib/open-checkout.ts
import { DodoPayments } from 'dodopayments-checkout';

type PlanId = 'starter' | 'pro';

async function createCheckoutUrl(planId: PlanId, quantity = 1): Promise<string> {
  const response = await fetch('/api/overlay-checkout', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ planId, quantity })
  });

  if (!response.ok) throw new Error('Failed to create checkout');

  const data = (await response.json()) as { checkoutUrl?: string };
  if (!data.checkoutUrl) throw new Error('Checkout URL was not returned');
  return data.checkoutUrl;
}

// Call ONCE when the app loads (e.g. in your root component or entry point),
// not before every checkout. Pick the display type your page uses.
export function initCheckout(displayType: 'overlay' | 'inline'): void {
  DodoPayments.Initialize({
    mode: 'test', // or 'live'
    displayType,
    onEvent: (event) => {
      console.log('Checkout event:', event);
    }
  });
}

// Requires initCheckout('overlay') to have run at app load.
export async function openOverlayCheckout(planId: PlanId): Promise<void> {
  const checkoutUrl = await createCheckoutUrl(planId);
  DodoPayments.Checkout.open({ checkoutUrl });
}

// Requires initCheckout('inline') to have run at app load.
export async function openInlineCheckout(planId: PlanId): Promise<void> {
  const checkoutUrl = await createCheckoutUrl(planId);
  DodoPayments.Checkout.open({
    checkoutUrl,
    elementId: 'dodo-inline-checkout'
  });
}
```

